import React, { useEffect, useRef, useState } from 'react';
import { Button, Typography, Space } from 'antd';
import { buildAuthHeaders } from '../api';

const GrafanaLauncher: React.FC = () => {
  const [url, setUrl] = useState<string>('');
  const [baseUrl, setBaseUrl] = useState<string>('');
  const [sysUrl] = useState<string>('');
  const [promUrl, setPromUrl] = useState<string>('');
  const [auxUrl, setAuxUrl] = useState<string>('');
  const [sysDashUrl, setSysDashUrl] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    (async () => {
      try {
        const resp = await fetch('/api/miniapp/grafana/ml', { headers: buildAuthHeaders() });
        if (resp.ok) {
          const data = await resp.json();
          const raw = String(data?.url || '');
          if (raw.startsWith('http')) {
            try {
              const u = new URL(raw);
              // Удаляем kiosk, чтобы оставить навигацию/поиск по дашбордам
              u.searchParams.delete('kiosk');
              setUrl(u.toString());
              // База для списка дашбордов — всё до "/d/"
              const idx = u.pathname.indexOf('/d/');
              if (idx > 0) {
                setBaseUrl(u.origin + u.pathname.slice(0, idx + 1));
              } else {
                setBaseUrl(u.origin + '/');
              }
            } catch {
              setUrl(raw);
            }
          }
          // Попытка получить явный путь Prometheus дашборда из настроек
          try {
            const r2 = await fetch('/api/admin/soul/settings/all', { headers: buildAuthHeaders() });
            if (r2.ok) {
              const j2 = await r2.json();
              const items = Array.isArray(j2?.items) ? j2.items : (Array.isArray(j2) ? j2 : []);
              const get = (k: string) => {
                try { return String((items.find((it: any) => String(it?.key||'') === k) || {}).value || ''); } catch { return ''; }
              };
              const baseFromSettings = get('grafana.base_url');
              const base = (baseFromSettings || baseUrl || url).toString();
              let promPath = get('grafana.prometheus_dashboard.path') || get('grafana.prom_dashboard.path') || get('grafana.prom.path');
              // Без хардкодов: если нет явного пути в БД — не подставляем дефолты
              if (promPath) {
                const ensure = (p: string) => p.startsWith('/') ? p : ('/' + p);
                const origin = (() => { try { const u2 = new URL(base); return u2.origin; } catch { return String(base).replace(/\/$/, ''); } })();
                setPromUrl(`${origin}${ensure(promPath)}?refresh=30s&kiosk`);
              }
              const auxPath = get('grafana.aux_llm_lima_dashboard.path');
              if (auxPath) {
                const ensure2 = (p: string) => p.startsWith('/') ? p : ('/' + p);
                const origin2 = (() => { try { const u3 = new URL(base); return u3.origin; } catch { return String(base).replace(/\/$/, ''); } })();
                setAuxUrl(`${origin2}${ensure2(auxPath)}?refresh=30s&kiosk`);
              }
              const sysPath = get('grafana.system_dashboard.path');
              if (sysPath) {
                try {
                  const ensure3 = (p: string) => p.startsWith('/') ? p : ('/' + p);
                  const origin3 = (() => { try { const u4 = new URL(base); return u4.origin; } catch { return String(base).replace(/\/$/, ''); } })();
                  const sys = `${origin3}${ensure3(sysPath)}?refresh=30s&kiosk`;
                  // Сохраним в state через setBaseUrl замену sysUrl — используем baseUrl как fallback
                  setBaseUrl(prev => prev || origin3 + '/grafana/');
                  // Переопределяем sysUrl через ссылку — используем промена переменной
                  (window as any).__SYS_DASH_URL__ = sys;
                } catch {}
              }
            }
          } catch {}
          // Параметризованные пути с сервера (готовые URL)
          try {
            const rp = await fetch('/api/miniapp/grafana/paths', { headers: buildAuthHeaders() });
            if (rp.ok) {
              const jp = await rp.json();
              if (jp?.prom_url) setPromUrl(String(jp.prom_url));
              if (jp?.aux_url) setAuxUrl(String(jp.aux_url));
              if (jp?.sys_url) setSysDashUrl(String(jp.sys_url));
            }
          } catch {}
        }
      } catch {
        // noop: keep default url
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const openExternalUrl = (u: string) => {
    try {
      const tg = (window as any).Telegram?.WebApp;
      if (tg && tg.openLink) tg.openLink(u, { try_instant_view: false });
      else window.open(u, '_blank', 'noopener');
    } catch { window.open(u, '_blank', 'noopener'); }
  };

  const getTarget = (): string => {
    try {
      const raw = (window.location.hash || '') + (window.location.search || '');
      const m = raw.match(/[?&]target=([^&]+)/);
      if (m) return decodeURIComponent(m[1]);
    } catch {}
    return '';
  };

  const didLaunchRef = useRef<boolean>(false);
  useEffect(() => {
    if (loading || didLaunchRef.current) return;
    const target = getTarget();
    const launchAndReturn = (u: string) => {
      didLaunchRef.current = true;
      openExternalUrl(u);
      setTimeout(() => {
        try { window.history.back(); }
        catch { try { window.location.hash = '#/architect'; } catch {} }
      }, 50);
    };
    if (target === 'ml' && url) {
      launchAndReturn(url);
    } else if (target === 'sys') {
      const sys = (window as any).__SYS_DASH_URL__ as string;
      const defaultSys = (() => {
        try {
          const origin = (() => { try { const u = new URL(baseUrl || url || '/'); return u.origin; } catch { return ''; } })();
          return origin ? (origin + '/grafana/d/system_metrics/system-metrics') : '/grafana/d/system_metrics/system-metrics';
        } catch { return '/grafana/d/system_metrics/system-metrics'; }
      })();
      const defaultList = (() => {
        try {
          const origin = (() => { try { const u = new URL(baseUrl || url || '/'); return u.origin; } catch { return ''; } })();
          return origin ? (origin + '/grafana/dashboards') : '/grafana/dashboards';
        } catch { return '/grafana/dashboards'; }
      })();
      launchAndReturn(sysDashUrl || sys || defaultSys || defaultList || sysUrl || baseUrl);
    } else if (target === 'prom') {
      // Открываем явный Prometheus‑дашборд из настроек; если не задан — fallback на базовую Grafana
      const u = promUrl || baseUrl;
      launchAndReturn(u);
    } else if (target === 'aux') {
      const u = auxUrl || baseUrl;
      launchAndReturn(u);
    }
  }, [loading, url, sysUrl, baseUrl]);

  // Если есть целевой параметр — ничего не рендерим (чтобы не мигало промежуточное окно)
  const hasTarget = (() => { try { return !!getTarget(); } catch { return false; } })();
  if (hasTarget) return null;

  return (
    <div style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24 }}>
      <div style={{ maxWidth: 520, width: '100%', textAlign: 'center', background: 'var(--sp-bg-card)', border: '1px solid var(--sp-border-primary)', borderRadius: 12, padding: 24 }}>
        <Typography.Title level={3} style={{ marginTop: 0, marginBottom: 12 }}>ML Grafana</Typography.Title>
        <Typography.Paragraph type="secondary" style={{ marginBottom: 16 }}>
          Авто‑открытие внешних отчётов Grafana в зависимости от цели.
        </Typography.Paragraph>
        <Space direction="vertical" size={12} style={{ width: '100%' }}>
          <Button type="primary" size="large" loading={loading} onClick={() => openExternalUrl(url || baseUrl)}>Открыть ML Dashboard</Button>
          <Button size="middle" onClick={() => openExternalUrl(sysDashUrl || sysUrl || '/grafana/d/system_metrics/system-metrics' || '/grafana/dashboards' || baseUrl)}>System Metrics</Button>
          <Button size="middle" onClick={() => openExternalUrl(promUrl || baseUrl)}>Метрики (Prometheus)</Button>
          <Button size="middle" onClick={() => openExternalUrl(auxUrl || baseUrl)}>Aux LLM / LIMA</Button>
          <Button size="middle" onClick={() => openExternalUrl(baseUrl)}>Открыть список дашбордов</Button>
          <div style={{ fontSize: 12, color: 'var(--sp-text-secondary)' }}>Ссылки открываются во внешнем окне Grafana.</div>
        </Space>
      </div>
    </div>
  );
};

export default GrafanaLauncher;


